from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import AllowAny
from rest_framework.response import Response
from rest_framework import status
from rest_framework.authtoken.models import Token
from django.contrib.auth import authenticate


@api_view(["POST"])
@permission_classes([AllowAny])
def obtain_token(request):
    username = request.data.get("username")
    password = request.data.get("password")

    if not username or not password:
        return Response(
            {"detail": "نام کاربری و رمز عبور الزامی است."},
            status=status.HTTP_400_BAD_REQUEST,
        )

    user = authenticate(username=username, password=password)
    if user is None:
        return Response(
            {"detail": "نام کاربری یا رمز عبور نادرست است."},
            status=status.HTTP_400_BAD_REQUEST,
        )

    token, created = Token.objects.get_or_create(user=user)
    return Response({"token": token.key})

from rest_framework.authentication import BaseAuthentication
from rest_framework.exceptions import AuthenticationFailed
from django.utils import timezone
from .models import ApiKey


class ApiKeyAuthentication(BaseAuthentication):
    """
    احراز هویت با هدر X-Api-Key.
    """

    def authenticate(self, request):
        api_key = request.headers.get("X-Api-Key")
        if not api_key:
            # این روش کاری نکرد — روش بعدی امتحان شود
            return None

        try:
            key = ApiKey.objects.select_related("user").get(key=api_key)
        except ApiKey.DoesNotExist:
            raise AuthenticationFailed("کلید API نامعتبر است.")

        if not key.is_active:
            raise AuthenticationFailed("کلید API غیرفعال است.")

        if key.expires_at and key.expires_at < timezone.now():
            raise AuthenticationFailed("کلید API منقضی شده است.")

        # به‌روزرسانی last_used
        ApiKey.objects.filter(pk=key.pk).update(last_used=timezone.now())

        return (key.user, key)   # (user, auth)

    def authenticate_header(self, request):
        # اگر خطا داده شد، این هدر در WWW-Authenticate برگردانده می‌شود
        # وجود آن باعث می‌شود DRF پاسخ 401 بدهد، نه 403
        return "X-Api-Key"

